    "python3 -c "import json,pathlib; m=json.load(open('.cursor/skills/skills-manifest.json')); root=pathlib.Path(m['skillsRoot']); missing=[];
for s in m.get('portableSkills',[])+m.get('skills',[]):
 e=s.get('entry');

 if e and not (root/e).exists(): missing.append(('entry', e))
 refdir=s.get('referencesDir');
 for k in (s.get('refKeywords') or {}):
  p=(root/refdir/k) if refdir else (root/k);
  if not p.exists(): missing.append(('ref', str(p)))
 print('MISSING', missing); raise SystemExit(1 if any(missing) else 0)""

